def gh(path):
    req = urllib.request.Request("https://api.github.com" + path, headers=HDR)
    try:
        with OP.open(req, timeout=30) as r:
            return json.loads(r.read().decode())
    except Exception as e:
        return {"__err__": type(e).__name__ + str(getattr(e, "code", ""))}

def fmt_star(n):
    if n >= 10000: return "\u2605%.1f\u4e07" % (n / 10000)
    if n >= 1000: return "\u2605%.1fk" % (n / 1000)
    return "\u2605%d" % n

def main():
    allrepos = [(n, sl, d, tag) for _, its in DATA for (n, sl, d, tag) in its]
    results = {}
    with cf.ThreadPoolExecutor(12) as ex:
        for item, j in ex.map(lambda it: (it, gh("/repos/" + it[1])), allrepos):
            results[item[1]] = j
    fails = [(k, v["__err__"]) for k, v in results.items() if "__err__" in v]
    star = {k: (v.get("stargazers_count", 0) if "__err__" not in v else -1) for k, v in results.items()}
    canonical = {k: (v.get("full_name", k) if "__err__" not in v else k) for k, v in results.items()}
    head = ["# 学习友链目录 \u00b7 Learning Ecosystem Directory\n",
            "> 超级完整的学习生态索引：**\u5171 %d 个热门学习项目**（全部为 GitHub 开源项目），按 17 个分区收录，每个仓库均经 GitHub API 批量核验，星数为构建当日快照。\n>",
            "> 与 [开源工具链](./tools.md) 的区别：`tools.md` 回答「十阶每一阶用什么工具」；本目录是更广的**学习生态友链** \u2014\u2014 找到同类工具、参考别人怎么学，甚至直接读它的源码学。\n>",
            "> 本目录由 [`generator/build_awesome.py`](https://github.com/HuanMoovo/fuxi/blob/main/generator/build_awesome.py) 可复现生成；收录标准：与「学习」直接相关、社区活跃、链接可访问；不收录取版资源。\n"]
    ok = 0; per = []; body = []
    for title, items in DATA:
        good = [(n, sl, d, tag) for (n, sl, d, tag) in items if star[sl] >= 0]
        good.sort(key=lambda x: -star[x[1]])
        per.append((title, len(good)))
        body.append("\n## " + title + "\n")
        for n, sl, d, tag in good:
            ok += 1
            body.append("- **[" + n + "](https://github.com/" + canonical[sl] + ")** " + fmt_star(star[sl]) + " \u2014 " + d + "。（适用阶：" + tag + "）")
    ap = os.path.join(ROOT, "generator", "awesome_auto.json")
    auto = 0
    auto_lines = []
    if os.path.exists(ap):
        import json as _json
        _ad = _json.load(open(ap, encoding="utf-8"))
        auto_lines += ["", "---", "", "## 自动采集区 · 国际开源项目与书籍", ""]
        auto_lines.append("> 由 `generator/harvest_awesome.py` 通过 GitHub Search API 自动采集并核验（采集日期：" + _ad.get("generated", "") + "）：全部条目可点击、可加载。")
        auto_lines.append("")
        for _sec in _ad.get("sections", []):
            auto_lines.append("## " + _sec["title"])
            auto_lines.append("")
            for _e in _sec["entries"]:
                auto += 1
                auto_lines.append("- **[" + _e["name"] + "](https://github.com/" + _e["full"] + ")** " + fmt_star(_e["stars"]) + " — " + _e["desc"])
            auto_lines.append("")
        auto_lines.append("> 自动采集区共 %d 个条目；与上方精选合计 **%d 个**。" % (auto, ok + auto))
    head[1] = head[1] % (ok + auto)
    head.append("\n**共收录 %d 个项目** \uff5c 分类导航：" % ok + " \u00b7 ".join("%s（%d）" % (c, k) for c, k in per) + "\n")
    head.append("> 想推荐新的学习项目？提 Issue 使用「新增工具/资源」模板，或直接改 `generator/build_awesome.py` 里的数据后提 PR：https://github.com/HuanMoovo/fuxi/issues/new/choose\n")
    out = os.path.join(ROOT, "docs", "awesome-learning.md")
    with open(out, "w", encoding="utf-8") as f:
        f.write("\n".join(head) + "\n".join(body) + "\n" + "\n".join(auto_lines) + ("\n" if auto_lines else ""))
    print("FAIL:", fails if fails else "NONE")
    print("WRITTEN:", ok, "entries ->", out)

if __name__ == "__main__":
    main()
